std::vector<std::pair<size_t, size_t>> collisions;
for (size_t i = 0; i < boxes.size(); ++i) {
    for (size_t j = i + 1; j < boxes.size(); ++j) {
        const auto& boxA = boxes[i];
        const auto& boxB = boxes[j];

        // Check for overlap on all axes
        bool overlapX = (boxA.minX <= boxB.maxX) && (boxB.minX <= boxA.maxX);
        bool overlapY = (boxA.minY <= boxB.maxY) && (boxB.minY <= boxA.maxY);
        bool overlapZ = (boxA.minZ <= boxB.maxZ) && (boxB.minZ <= boxA.maxZ);

        if (overlapX && overlapY && overlapZ) {
            collisions.emplace_back(i, j);
        }
    }
}
return collisions;
// END_CODE

